KYO_Shrine_navy_scripte = {
  # 第一次呼叫時，補上精神與動態加成

  if = { limit = { NOT = { has_dynamic_modifier = { modifier = Shrine_navy_modifiers } } } add_dynamic_modifier = { modifier = Shrine_navy_modifiers } }

  # 確保所有用到的變數存在（沒有就設 0）
  if = { limit = { NOT = { has_variable = Shrine_navy_var_transport_capacity } } set_variable = { var = Shrine_navy_var_transport_capacity value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_naval_strike } } set_variable = { var = Shrine_navy_var_naval_strike value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_naval_hit_chance } } set_variable = { var = Shrine_navy_var_naval_hit_chance value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_sortie_efficiency } } set_variable = { var = Shrine_navy_var_sortie_efficiency value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_naval_speed_factor } } set_variable = { var = Shrine_navy_var_naval_speed_factor value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_experience_gain_navy } } set_variable = { var = Shrine_navy_var_experience_gain_navy value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_spotting_chance } } set_variable = { var = Shrine_navy_var_spotting_chance value = 0 } }
  if = { limit = { NOT = { has_variable = Shrine_navy_var_navy_submarine_detection_factor } } set_variable = { var = Shrine_navy_var_navy_submarine_detection_factor value = 0 } }


}

